SELECT DISTINCT md.chembl_id, md.pref_name, cs.canonical_smiles, md.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id AS target_chembl_id, td.pref_name AS target_name FROM molecule_dictionary md JOIN drug_mechanism dm ON dm.molregno = md.molregno JOIN compound_structures cs ON cs.molregno = md.molregno LEFT JOIN target_dictionary td ON dm.tid = td.tid WHERE md.max_phase = 4 AND cs.canonical_smiles IS NOT NULL ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, md.max_phase, dm.mechanism_of_action, dm.action_type, td.chembl_id, td.pref_name
